import { AnchorViewpoint } from "../types/viewer";

export const TOTAL_FRAMES = 120;

/** Frame shown on first load / reset (Anchor View 01). */
export const INITIAL_FRAME = 10;

/**
 * Two quality tiers generated by `scripts/build-frames.mjs`:
 *  - "lq": 960x540 WebP (~30-60 KB) -> preloaded for every frame, used for instant paint & fast drag
 *  - "hq": 2560x1440 WebP           -> streamed only around the current viewpoint (bounded cache)
 */
export type FrameTier = "lq" | "hq";

export const FRAME_BASE_PATH = "/frames";

export const OFFICIAL_ANCHOR_FRAMES: readonly number[] = [10, 30, 50, 70, 90, 110] as const;

