/**
 * Normalizes any frame number (including float and negative) into the continuous [1, totalFrames] circular range.
 */
export function wrapFrame(frame: number, totalFrames: number = TOTAL_FRAMES): number {
  const norm = ((frame - 1) % totalFrames + totalFrames) % totalFrames;
  return norm + 1;
}

/**
 * Calculates the shortest signed circular distance from f1 to f2.
 * Positive returned value means clockwise (forward), negative means counter-clockwise.
 * Range: [-totalFrames/2, +totalFrames/2]
 */
export function circularDistance(f1: number, f2: number, totalFrames: number = TOTAL_FRAMES): number {
  const delta = f2 - f1;
  const half = totalFrames / 2;
  return ((delta + half) % totalFrames + totalFrames) % totalFrames - half;
}

/**
 * Calculates absolute circular distance between two frames.
 */
export function absCircularDistance(f1: number, f2: number, totalFrames: number = TOTAL_FRAMES): number {
  return Math.abs(circularDistance(f1, f2, totalFrames));
}

/**
 * Rounds any (float / negative / overflowing) frame value to an integer frame index in [1, totalFrames].
 * Note: Math.round(wrapFrame(x)) alone can yield totalFrames + 1 (e.g. 120.6 -> 121), so we wrap after rounding.
 */
export function toFrameIndex(frame: number, totalFrames: number = TOTAL_FRAMES): number {
  return wrapFrame(Math.round(frame), totalFrames);
}

/**
 * Converts a frame number (1-120) to azimuth degrees (0° to 357°).
 */
export function frameToAzimuth(frame: number, totalFrames: number = TOTAL_FRAMES): number {
  const wrapped = wrapFrame(frame, totalFrames);
  const deg = ((wrapped - 1) / totalFrames) * 360;
  return Math.round(deg * 10) / 10;
}

/**
 * Finds the nearest predefined anchor viewpoint to a given frame.
 */
export function findNearestAnchor(
  frame: number,
  anchors: readonly number[] = OFFICIAL_ANCHOR_FRAMES,
  totalFrames: number = TOTAL_FRAMES
): {
  anchorFrame: number;
  viewpoint: AnchorViewpoint | null;
  signedDistance: number;
  absDistance: number;
} {
  let minAbsDist = Infinity;
  let bestAnchor = anchors[0];
  let bestSigned = 0;

  for (const anchor of anchors) {
    const signed = circularDistance(frame, anchor, totalFrames);
    const abs = Math.abs(signed);
    if (abs < minAbsDist) {
      minAbsDist = abs;
      bestAnchor = anchor;
      bestSigned = signed;
    }
  }

  const viewpoint = ANCHOR_VIEWPOINTS.find((v) => v.frame === bestAnchor) || null;

  return {
    anchorFrame: bestAnchor,
    viewpoint,
    signedDistance: bestSigned,
    absDistance: minAbsDist,
  };
}

/**
 * Smooth cubic easing out: fast start, soft deceleration.
 */
export function easeOutCubic(t: number): number {
  return 1 - Math.pow(1 - t, 3);
}

/**
 * Smooth quartic easing out.
 */
export function easeOutQuart(t: number): number {
  return 1 - Math.pow(1 - t, 4);
}

/**
 * Resolves the URL of a frame (1-120) for the requested quality tier, e.g. frame 7 -> /frames/hq/007.webp
 */
export function getFrameUrl(frame: number, tier: FrameTier): string {
  const index = toFrameIndex(frame);
  return `${FRAME_BASE_PATH}/${tier}/${String(index).padStart(3, "0")}.webp`;
}


